const item = $json;

const text =
  item.content?.parts?.[0]?.text ||
  item.text ||
  item.output ||
  "";

if (!text) {
  throw new Error("Gemini text output was not found.");
}

const cleanText = text
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

const data = JSON.parse(cleanText);

return {
  json: data
};
